        for (CheckoutRequest.ItemRequest i : brutos) {
            if (i == null) {
                itens.add(null);
                continue;
            }
            itens.add(new Item(
                    i.nome(),
                    i.precoUnitario(),
                    i.quantidade() == null ? 0 : i.quantidade(),
                    i.pesoKg()
            ));
        }
        return itens;
    }
}

