4	import java.util.ArrayList;
5	import java.util.List;
6	import org.springframework.stereotype.Component;
7	
8	@Component
9	public class CalculadoraResumo {
10	
11	    public Resumo calcular(Entrada entrada) {
12	        List<Item> itens = validarItens(entrada.itens());
13	        NivelClube nivel = parseEnum(NivelClube.class, entrada.nivelClube(), "NIVEL_CLUBE_INVALIDO");
14	        Regiao regiao = parseEnum(Regiao.class, entrada.regiao(), "REGIAO_INVALIDA");
15	        Modalidade modalidade = parseEnum(Modalidade.class, entrada.modalidadeEntrega(), "MODALIDADE_INVALIDA");
16	
17	        BigDecimal subtotal = Dinheiro.cent(itens.stream()
18	                .map(Item::subtotal)
19	                .reduce(BigDecimal.ZERO, BigDecimal::add));
20	        BigDecimal pesoTotal = itens.stream()
21	                .map(Item::pesoTotal)
22	                .reduce(BigDecimal.ZERO, BigDecimal::add);
23	
24	        if (!modalidade.atende(pesoTotal)) {
25	            throw new ErroCalculo("MODALIDADE_INDISPONIVEL");
26	        }
27	
28	        BigDecimal frete = nivel.pagaFrete()
29	                ? Dinheiro.cent(modalidade.custo(pesoTotal))
30	                : Dinheiro.ZERO;
31	
32	        Cupom cupom = null;
33	        if (entrada.cupom() != null && !entrada.cupom().isBlank()) {
34	            cupom = parseEnum(Cupom.class, entrada.cupom(), "CUPOM_INVALIDO");
35	            if (!cupom.aplicavel(itens, subtotal, frete)) {
36	                throw new ErroCalculo("CUPOM_NAO_APLICAVEL");
37	            }
38	        }
39	
40	        BigDecimal desconto = cupom == null
41	                ? Dinheiro.ZERO
42	                : Dinheiro.cent(cupom.desconto(itens, subtotal, frete));
43	        BigDecimal seguro = regiao.seguro(subtotal);
44	        BigDecimal totalPedido = Dinheiro.cent(
45	                subtotal.subtract(desconto).add(frete).add(seguro));
46	
47	        FormaPagamento forma = parseEnum(FormaPagamento.class, entrada.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
48	        int parcelas = entrada.parcelas() == null ? 1 : entrada.parcelas();
49	        if (!forma.parcelasValidas(parcelas)) {
50	            throw new ErroCalculo("PARCELAMENTO_INVALIDO");
51	        }
52	        if (!forma.atende(totalPedido)) {
53	            throw new ErroCalculo("FORMA_PAGAMENTO_INDISPONIVEL");
54	        }
55	
56	        FormaPagamento.Resultado rp = forma.calcular(totalPedido, parcelas);
57	
58	        return new Resumo(
59	                subtotal,
60	                desconto,
61	                frete,
