73	    private static List<Item> validarItens(List<Item> brutos) {
74	        if (brutos == null || brutos.isEmpty()) {
75	            throw new ErroCalculo("PEDIDO_INVALIDO");
76	        }
77	        List<Item> itens = new ArrayList<>(brutos.size());
78	        for (Item i : brutos) {
79	            if (i == null
80	                    || i.precoUnitario() == null
81	                    || i.precoUnitario().signum() <= 0
82	                    || i.quantidade() <= 0
83	                    || i.pesoKg() == null
84	                    || i.pesoKg().signum() <= 0) {
85	                throw new ErroCalculo("PEDIDO_INVALIDO");
86	            }
87	            itens.add(i);
88	        }
89	        return itens;
90	    }
