1	package com.loja.checkout.domain;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	public enum FormaPagamento {
7	    PIX {
8	        @Override public boolean parcelasValidas(int n) { return n == 1; }
9	        @Override public boolean atende(BigDecimal totalPedido) { return true; }
10	        @Override public Resultado calcular(BigDecimal totalPedido, int n) {
11	            BigDecimal desconto = Dinheiro.cent(totalPedido.multiply(new BigDecimal("0.05")));
12	            BigDecimal totalFinal = Dinheiro.cent(totalPedido.subtract(desconto));
13	            return new Resultado(desconto.negate(), totalFinal, totalFinal);
14	        }
15	    },
16	    CARTAO {
17	        @Override public boolean parcelasValidas(int n) { return n >= 1 && n <= 12; }
18	        @Override public boolean atende(BigDecimal totalPedido) { return true; }
19	        @Override public Resultado calcular(BigDecimal totalPedido, int n) {
20	            if (n <= 3) {
21	                BigDecimal parcela = totalPedido
22	                        .divide(BigDecimal.valueOf(n), 2, RoundingMode.HALF_EVEN);
23	                return new Resultado(Dinheiro.ZERO, Dinheiro.cent(totalPedido), parcela);
24	            }
25	            double tx = 0.0199;
26	            double fator = tx / (1.0 - Math.pow(1.0 + tx, -n));
27	            BigDecimal parcela = Dinheiro.cent(totalPedido.multiply(BigDecimal.valueOf(fator)));
28	            BigDecimal totalFinal = Dinheiro.cent(parcela.multiply(BigDecimal.valueOf(n)));
29	            BigDecimal ajuste = Dinheiro.cent(totalFinal.subtract(totalPedido));
30	            return new Resultado(ajuste, totalFinal, parcela);
31	        }
32	    },
33	    BOLETO {
34	        private final BigDecimal tarifa = new BigDecimal("3.49");
35	        private final BigDecimal limite = new BigDecimal("1000.00");
36	
37	        @Override public boolean parcelasValidas(int n) { return n == 1; }
38	        @Override public boolean atende(BigDecimal totalPedido) {
39	            return totalPedido.compareTo(limite) <= 0;
40	        }
41	        @Override public Resultado calcular(BigDecimal totalPedido, int n) {
42	            BigDecimal totalFinal = Dinheiro.cent(totalPedido.add(tarifa));
43	            return new Resultado(tarifa, totalFinal, totalFinal);
44	        }
45	    };
46	
47	    public abstract boolean parcelasValidas(int n);
48	    public abstract boolean atende(BigDecimal totalPedido);
49	    public abstract Resultado calcular(BigDecimal totalPedido, int n);
50	
51	    public record Resultado(BigDecimal ajuste, BigDecimal totalFinal, BigDecimal valorParcela) {}
52	}
